// 커밋된 ./wiki (seed 골격)를 ./wiki-runtime (런타임 위키 = 별도 git repo)로 초기화한다.
// 런타임 위키는 앱 코드 repo와 분리된 자체 git repo이며, 인제스트 워커가 유일한 라이터다.
// 재실행 안전: 이미 git repo가 있으면 보존한다. 리셋하려면 wiki-runtime 폴더를 지우고 재실행.
// 근거: docs/03 §2(git-backed, 단일 라이터), docs/04 §2(레이아웃).

import { existsSync, cpSync, mkdirSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { resolve } from "node:path";

const SEED = resolve("wiki");
const RUNTIME = resolve(process.env.WIKI_REPO_PATH || "wiki-runtime");

function git(args) {
  return execFileSync("git", args, { cwd: RUNTIME }).toString().trim();
}

if (!existsSync(SEED)) {
  console.error(`✗ seed 위키가 없습니다: ${SEED}`);
  process.exit(1);
}

if (existsSync(resolve(RUNTIME, ".git"))) {
  console.log(`• 런타임 위키가 이미 있습니다 (보존): ${RUNTIME}`);
  process.exit(0);
}

console.log(`• seed 복사: ${SEED} → ${RUNTIME}`);
mkdirSync(RUNTIME, { recursive: true });
cpSync(SEED, RUNTIME, { recursive: true });

console.log("• git repo 초기화 + 최초 커밋");
git(["init", "-b", "main"]);
// 워커 정체성을 사람 커밋과 구분 (provenance)
git(["config", "user.name", "llm-wiki-worker"]);
git(["config", "user.email", "worker@llm-wiki.local"]);
git(["add", "-A"]);
git(["commit", "-m", "chore: seed wiki skeleton"]);

console.log(`✓ 런타임 위키 초기화 완료: ${RUNTIME}`);
console.log(git(["log", "--oneline"]));

