import { NextResponse } from "next/server";
import { promises as fs } from "node:fs";
import path from "node:path";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
import { wikiAbsPath, assertInScope } from "@/lib/wiki/paths";
import { assertWikiReady, commitAll, withWikiWriteLock } from "@/lib/wiki/repo";

// 위키 페이지 아카이브 — 삭제 시 `{scope}/.archive/` 로 이동(질의·검색·트리에서 자동 제외, docs/15 §5).
// 복원·영구삭제도 여기서. 모든 쓰기는 단일 라이터(withWikiWriteLock+commitAll). 룸 관리자만(canManageScope).
export const runtime = "nodejs";

const ARCHIVE_DIR = ".archive";

// `.archive/` 하위 .md 목록(트리의 자동 `.`-스킵 때문에 별도 워커 필요).
async function listArchived(absDir: string, relBase: string): Promise<string[]> {
  let entries: import("node:fs").Dirent[];
  try {
    entries = await fs.readdir(absDir, { withFileTypes: true });
  } catch {
    return [];
  }
  const out: string[] = [];
  for (const e of entries) {
    const rel = `${relBase}/${e.name}`;
    if (e.isDirectory()) out.push(...(await listArchived(path.join(absDir, e.name), rel)));
    else if (e.name.endsWith(".md")) out.push(rel);
  }
  return out;
}

// 아카이브 경로(`{scope}/.archive/<상대>`) ↔ 원위치(`{scope}/<상대>`) 변환.
function toArchivePath(wikiScope: string, pagePath: string): string {
  const rel = pagePath === wikiScope ? "" : pagePath.slice(wikiScope.length + 1); // scope 접두 제거
  return `${wikiScope}/${ARCHIVE_DIR}/${rel}`;
}
function fromArchivePath(wikiScope: string, archivedPath: string): string {
  const prefix = `${wikiScope}/${ARCHIVE_DIR}/`;
  const rel = archivedPath.startsWith(prefix) ? archivedPath.slice(prefix.length) : archivedPath;
  return `${wikiScope}/${rel}`;
}

// index.md에서 이 페이지를 가리키는 줄을 best-effort로 제거(컨텍스트 밖이라 인용 불가지만 목차 정합성).
async function pruneIndexLine(wikiScope: string, pagePath: string): Promise<void> {
  const idxAbs = wikiAbsPath(`${wikiScope}/index.md`);
  let content: string;
  try {
    content = await fs.readFile(idxAbs, "utf8");
  } catch {
    return; // index 없으면 무시
  }
  const relAfterScope = pagePath.slice(wikiScope.length + 1); // 예: entities/foo.md
  const slug = path.basename(pagePath, ".md");
  const kept = content
    .split("\n")
    .filter((line) => !(line.includes(relAfterScope) || line.includes(`[[${slug}]]`)));
  const next = kept.join("\n");
  if (next !== content) await fs.writeFile(idxAbs, next, "utf8");
}

async function frontmatterTitle(abs: string, fallback: string): Promise<string> {
  try {
    const c = await fs.readFile(abs, "utf8");
    const fm = c.match(/^---\n([\s\S]*?)\n---/);
    const tm = fm && fm[1].match(/^title:\s*(.+)$/m);
    if (tm) return tm[1].trim().replace(/^["']|["']$/g, "");
  } catch { /* */ }
  return fallback;
}

// GET ?scope= → 아카이브된 페이지 목록(복원/영구삭제 뷰). ACL: 접근 가능 scope.
export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const scope = new URL(req.url).searchParams.get("scope") ?? "";
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  const canManage = await canManageScope(user, wikiScope);
  const archiveBase = `${wikiScope}/${ARCHIVE_DIR}`;
  const files = (await listArchived(wikiAbsPath(archiveBase), archiveBase)).sort();
  const pages = await Promise.all(
    files.map(async (f) => ({
      path: f,
      originalPath: fromArchivePath(wikiScope, f),
      title: await frontmatterTitle(wikiAbsPath(f), path.basename(f, ".md")),
    })),
  );
  return NextResponse.json({ scope: wikiScope, pages, canManage });
}

// POST {scope, path, action:'archive'|'restore'|'delete'} — 룸 관리자만.
export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const scope = typeof body.scope === "string" ? body.scope : "";
  const pagePath = typeof body.path === "string" ? body.path : "";
  const action = body.action as "archive" | "restore" | "delete";
  if (!pagePath.endsWith(".md")) return NextResponse.json({ error: "md 페이지만 가능합니다." }, { status: 400 });
  if (!["archive", "restore", "delete"].includes(action)) {
    return NextResponse.json({ error: "action은 archive|restore|delete 중 하나입니다." }, { status: 400 });
  }
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  if (!(await canManageScope(user, wikiScope))) {
    return NextResponse.json({ error: "이 룸의 관리자만 할 수 있습니다 (OWNER·ADMIN)." }, { status: 403 });
  }

  await assertWikiReady();
  try {
    if (action === "archive") {
      // 활성 페이지 → .archive/ 로 이동
      assertInScope(wikiScope, pagePath);
      const dest = toArchivePath(wikiScope, pagePath);
      assertInScope(wikiScope, dest);
      const srcAbs = wikiAbsPath(pagePath);
      const destAbs = wikiAbsPath(dest);
      const sha = await withWikiWriteLock(async () => {
        await fs.mkdir(path.dirname(destAbs), { recursive: true });
        await fs.rename(srcAbs, destAbs);
        await pruneIndexLine(wikiScope, pagePath);
        return commitAll(`archive-page(${wikiScope}): ${pagePath}`, { team: wikiScope, gate: "PAGE_ARCHIVED" });
      });
      return NextResponse.json({ ok: true, archivedPath: dest, commit: sha });
    }
    if (action === "restore") {
      // .archive/ 페이지 → 원위치로 복원
      assertInScope(wikiScope, pagePath);
      const dest = fromArchivePath(wikiScope, pagePath);
      assertInScope(wikiScope, dest);
      const srcAbs = wikiAbsPath(pagePath);
      const destAbs = wikiAbsPath(dest);
      const sha = await withWikiWriteLock(async () => {
        await fs.mkdir(path.dirname(destAbs), { recursive: true });
        await fs.rename(srcAbs, destAbs);
        return commitAll(`restore-page(${wikiScope}): ${dest}`, { team: wikiScope, gate: "PAGE_RESTORED" });
      });
      return NextResponse.json({ ok: true, restoredPath: dest, commit: sha });
    }
    // delete(영구) — 아카이브 안의 파일만 삭제 가능(실수로 활성 페이지 영구삭제 방지)
    assertInScope(wikiScope, pagePath);
    if (!pagePath.startsWith(`${wikiScope}/${ARCHIVE_DIR}/`)) {
      return NextResponse.json({ error: "영구삭제는 아카이브된 페이지만 가능합니다." }, { status: 400 });
    }
    const sha = await withWikiWriteLock(async () => {
      await fs.unlink(wikiAbsPath(pagePath));
      return commitAll(`delete-page(${wikiScope}): ${pagePath}`, { team: wikiScope, gate: "PAGE_DELETED" });
    });
    return NextResponse.json({ ok: true, deletedPath: pagePath, commit: sha });
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 400 });
  }
}

