import { prisma } from "@/lib/db";
import type { User } from "@prisma/client";

// ── ACL 단일 계산처 (docs/07 §2, docs/11 §6, REQ-AUTH-004) ──────────
// "사용자의 허용 scope 집합"을 한 곳에서 계산한다. 질의 입력·페이지 로드·인제스트 적용·
// 누적 파일링 등 모든 강제지점이 이 함수를 공용 호출한다.

export type ScopeKind = "common" | "personal" | "project";

export interface AllowedScope {
  id: string; // 'common' | 'personal:<userId>' | 'project-<slug>'
  kind: ScopeKind;
  name: string;
  isOwner?: boolean;
}

/** scope id 규칙 */
export const personalScopeId = (userId: number) => `personal:${userId}`;
export const projectScopeId = (slug: string) => `project-${slug}`;

/** 사용자가 접근 가능한 scope 목록(공통 + 내 룸 + 개인). */
export async function allowedScopes(user: User): Promise<AllowedScope[]> {
  const memberships = await prisma.projectMembership.findMany({
    where: { userId: user.id },
    include: { project: true },
    orderBy: { createdAt: "asc" },
  });
  const rooms: AllowedScope[] = memberships
    .filter((m) => !m.project.archivedAt)
    .map((m) => ({
      id: projectScopeId(m.project.slug),
      kind: "project",
      name: m.project.name,
      isOwner: m.role === "OWNER",
    }));
  return [
    { id: "common", kind: "common", name: "회사공통" },
    ...rooms,
    { id: personalScopeId(user.id), kind: "personal", name: "내 위키" },
  ];
}

/** 허용 scope 밖이면 throw (ACL 강제). */
export async function assertScopeAllowed(user: User, scopeId: string): Promise<void> {
  const ok = (await allowedScopes(user)).some((s) => s.id === scopeId);
  if (!ok) throw new Error(`scope 접근 거부: ${scopeId}`);
}

/**
 * 룸 ★관리 권한★(아카이브·편집·영구삭제용) — ADMIN | 개인위키 본인 | 룸 OWNER. common = ADMIN만.
 * teamScope = 위키 디렉터리 접두(scopeWikiPrefix 결과: 'common'·'personal/<id>'·'project-<slug>').
 * (자료 삭제의 기존 canDelete에서 ★업로더 경로를 뺀★ = "룸 관리자만".)
 */
export async function canManageScope(user: User, teamScope: string): Promise<boolean> {
  if (user.role === "ADMIN") return true;
  if (teamScope === `personal/${user.id}`) return true;
  if (teamScope.startsWith("project-")) {
    const project = await prisma.project.findUnique({ where: { slug: teamScope.slice("project-".length) } });
    if (!project || project.archivedAt) return false;
    const m = await prisma.projectMembership.findUnique({
      where: { userId_projectId: { userId: user.id, projectId: project.id } },
    });
    return m?.role === "OWNER";
  }
  return false; // common = ADMIN만(위에서 처리)
}

/** scope id → 위키 디렉터리 경로(파일시스템 안전). 'personal:7' → 'personal/7'. */
export function scopeWikiPrefix(scopeId: string): string {
  if (scopeId === "common") return "common";
  if (scopeId.startsWith("personal:")) return `personal/${scopeId.slice("personal:".length)}`;
  return scopeId; // project-<slug>
}

