import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { adminUserUsage } from "@/lib/cost";
import { getDailyTokenLimit, setDailyTokenLimit } from "@/lib/settings";

// 관리자 전용: 사용자별 사용량 조회(GET) + 일일 토큰 상한 설정(POST). 토큰 절약 경각심 운영용.
export const runtime = "nodejs";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  if (user.role !== "ADMIN") return NextResponse.json({ error: "관리자만 볼 수 있습니다." }, { status: 403 });
  return NextResponse.json({ users: await adminUserUsage(), dailyLimit: await getDailyTokenLimit() });
}

export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  if (user.role !== "ADMIN") return NextResponse.json({ error: "관리자만 변경할 수 있습니다." }, { status: 403 });
  const { dailyLimit } = await req.json().catch(() => ({}));
  if (typeof dailyLimit !== "number" || !Number.isFinite(dailyLimit) || dailyLimit < 0) {
    return NextResponse.json({ error: "dailyLimit(0 이상 숫자)이 필요합니다. 0=무제한." }, { status: 400 });
  }
  await setDailyTokenLimit(dailyLimit);
  return NextResponse.json({ ok: true, dailyLimit: await getDailyTokenLimit() });
}

