import { simpleGit, type SimpleGit } from "simple-git";
import { wikiRoot } from "./paths";

function git(): SimpleGit {
  return simpleGit(wikiRoot());
}

// ── 단일 라이터 보장 ───────────────────────────────────────────────
// MVP는 인제스트 워커가 웹 요청 안에서 인라인으로 돈다. 동시 요청이 같은
// 작업트리를 건드리지 않도록 프로세스 내 쓰기를 직렬화한다(파일수정→add→commit
// 전체가 한 임계구역). Phase 3에서 워커를 별도 프로세스로 분리하면 이 락은
// 프로세스 분리 자체로 대체된다. 근거: docs/03 §1, REQ-OPS-003.
let writeChain: Promise<unknown> = Promise.resolve();

export function withWikiWriteLock<T>(fn: () => Promise<T>): Promise<T> {
  const run = writeChain.then(fn, fn);
  // 다음 대기자가 이전 실패에 막히지 않도록 체인에서는 에러를 흡수.
  writeChain = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

export interface CommitTrailers {
  sourceSha256?: string;
  sourceType?: string;
  team?: string;
  confidence?: number;
  gate?: string;
  model?: string;
}

function buildMessage(subject: string, t: CommitTrailers): string {
  const lines = [
    t.sourceSha256 && `Source-Sha256: ${t.sourceSha256}`,
    t.sourceType && `Source-Type: ${t.sourceType}`,
    t.team && `Team: ${t.team}`,
    t.confidence != null && `Confidence: ${t.confidence}`,
    t.gate && `Gate: ${t.gate}`,
    t.model && `Model: ${t.model}`,
  ].filter(Boolean) as string[];
  return lines.length ? `${subject}\n\n${lines.join("\n")}` : subject;
}

/**
 * 위키 작업트리 변경을 전부 스테이징하고 provenance trailer와 함께 커밋한다.
 * 반드시 withWikiWriteLock 임계구역 안에서 호출할 것. 새 커밋 sha를 반환.
 */
export async function commitAll(
  subject: string,
  trailers: CommitTrailers = {},
): Promise<string> {
  const g = git();
  await g.add("-A");
  const res = await g.commit(buildMessage(subject, trailers));
  return res.commit;
}

/** 런타임 위키가 초기화돼 있는지(.git 존재) 확인. 미초기화면 명확한 안내. */
export async function assertWikiReady(): Promise<void> {
  const g = git();
  const isRepo = await g.checkIsRepo();
  if (!isRepo) {
    throw new Error(
      `런타임 위키가 초기화되지 않았습니다(${wikiRoot()}). \`npm run wiki:init\`을 먼저 실행하세요.`,
    );
  }
}
